import { verifyProofAction } from '@/app/actions';
import { Empty, PageHeader, Status } from '@/components/ui';
import { api } from '@/lib/api';

type Event = { txId: string; eventType: string; batchId: string | null; blockNumber: string | null; actorMsp: string | null; payloadHash: string | null; status: string | null; verificationStatus: string | null; observedAt: string | null };

export default async function BlockchainPage({ searchParams }: { searchParams: Promise<{ verified?: string }> }) {
  const [data, params] = await Promise.all([api<{ events: Event[]; total: number }>('/api/admin/fabric/events?limit=100'), searchParams]);
  return <main className="page"><PageHeader kicker="Cryptographic evidence" title="On-chain event register" description="Chaincode events, block references, submitting MSPs, and independently rechecked hash anchors." aside={<div className="network-seal"><span>Channel</span><strong>honeychannel</strong><small>3 organizations</small></div>} />
    {params.verified ? <p className="success-banner">Proof check completed for transaction {params.verified.slice(0, 18)}…</p> : null}
    <section className="panel table-panel">{data.events.length ? <div className="table-wrap"><table><thead><tr><th>Block / transaction</th><th>Event</th><th>Actor</th><th>Payload anchor</th><th>Proof</th></tr></thead><tbody>{data.events.map((event) => <tr key={event.txId}><td><strong>#{event.blockNumber ?? 'pending'}</strong><code>{event.txId.slice(0, 24)}…</code></td><td><strong>{event.eventType}</strong><small>{event.batchId}</small><Status>{event.status ?? 'COMMITTED'}</Status></td><td>{event.actorMsp ?? 'Unknown MSP'}</td><td><code>{event.payloadHash ? `${event.payloadHash.slice(0, 25)}…` : 'No hash'}</code></td><td>{event.verificationStatus ? <Status>{event.verificationStatus}</Status> : event.payloadHash ? <form action={verifyProofAction}><input type="hidden" name="transactionId" value={event.txId}/><button className="button compact" type="submit">Verify anchor</button></form> : 'Not verifiable'}</td></tr>)}</tbody></table></div> : <Empty>No events have been indexed. Enable the Fabric event indexer after deploying the network.</Empty>}</section>
  </main>;
}
